(() => {
  // (ROADMAP 11.28 tests) each thing of the pen drawn by the car as its legend shows it (a hand's copy of
  // the icon), made as that thing (pen.force: whatever it is read as) - the morph run on the game clock
  const g = window.__game;
  window.g = g;
  let seed = 4321;
  const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const nrm = () => Math.sqrt(-2 * Math.log(rnd() + 1e-9)) * Math.cos(2 * Math.PI * rnd());
  window.__seed = (s) => { seed = s; return s; };
  const circ = (cx, cy, r, n = 20) => Array.from({ length: n + 1 }, (_, i) => [cx + Math.cos((i / n) * Math.PI * 2) * r, cy + Math.sin((i / n) * Math.PI * 2) * r]);
  // an icon's strokes (M L H V C Q A Z, circles, rects)
  function svgStrokes(svg) {
    const out = [];
    for (const m of svg.matchAll(/<circle cx="([\d.]+)" cy="([\d.]+)" r="([\d.]+)"\/>/g)) out.push(circ(+m[1], +m[2], +m[3]));
    for (const m of svg.matchAll(/<rect x="([\d.]+)" y="([\d.]+)" width="([\d.]+)" height="([\d.]+)"(?: rx="[\d.]+")?(?: transform="rotate\(([-\d.]+) ([\d.]+) ([\d.]+)\)")?\/>/g)) {
      const [x, y, w, h] = [+m[1], +m[2], +m[3], +m[4]];
      let P = [[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]];
      if (m[5]) { const a = (+m[5] * Math.PI) / 180; const cx = +m[6]; const cy = +m[7]; P = P.map(([px, py]) => [cx + (px - cx) * Math.cos(a) - (py - cy) * Math.sin(a), cy + (px - cx) * Math.sin(a) + (py - cy) * Math.cos(a)]); }
      out.push(P);
    }
    for (const m of svg.matchAll(/<path d="([^"]+)"\/>/g)) {
      const toks = m[1].match(/[MLHVCQAZ]|-?\d*\.?\d+/g);
      let cur = null, x = 0, y = 0, start = null, cmd = 'M', i = 0;
      while (i < toks.length) {
        if (/[MLHVCQAZ]/.test(toks[i])) cmd = toks[i++];
        if (cmd === 'Z') { if (cur && start) cur.push(start.slice()); cur = null; continue; }
        if (cmd === 'M') { x = +toks[i++]; y = +toks[i++]; cur = [[x, y]]; out.push(cur); start = [x, y]; cmd = 'L'; }
        else if (cmd === 'L') { x = +toks[i++]; y = +toks[i++]; cur.push([x, y]); }
        else if (cmd === 'H') { x = +toks[i++]; cur.push([x, y]); }
        else if (cmd === 'V') { y = +toks[i++]; cur.push([x, y]); }
        else if (cmd === 'C') { const [x1, y1, x2, y2, x3, y3] = toks.slice(i, i + 6).map(Number); i += 6; for (let t = 0.125; t <= 1.001; t += 0.125) { const u = 1 - t; cur.push([u*u*u*x + 3*u*u*t*x1 + 3*u*t*t*x2 + t*t*t*x3, u*u*u*y + 3*u*u*t*y1 + 3*u*t*t*y2 + t*t*t*y3]); } x = x3; y = y3; }
        else if (cmd === 'Q') { const [x1, y1, x2, y2] = toks.slice(i, i + 4).map(Number); i += 4; for (let t = 0.125; t <= 1.001; t += 0.125) { const u = 1 - t; cur.push([u*u*x + 2*u*t*x1 + t*t*x2, u*u*y + 2*u*t*y1 + t*t*y2]); } x = x2; y = y2; }
        else if (cmd === 'A') { const [rx, , , , , x2, y2] = toks.slice(i, i + 7).map(Number); i += 7; const mx = (x + x2) / 2, my = (y + y2) / 2; for (let t = 0.2; t <= 1.001; t += 0.2) { cur.push([x + (x2 - x) * t + (my - y) * 0 , y + (y2 - y) * t - Math.sin(t * Math.PI) * rx * 0.3]); } x = x2; y = y2; }
      }
    }
    return out.filter((L) => L.length >= 2);
  }
  window.__svg = svgStrokes;
  const safe = () => { const W = innerWidth, H = innerHeight; return g.touch ? { x0: 236, x1: W - 118, y0: 50, y1: H - 124 } : { x0: 24, x1: W - 24, y0: 60, y1: H - 192 }; };
  const box = () => { const t = g.fuse.vehTarget(g.player.inVehicle); const F = g.fuse.frameOf(t); return F ? F.box : null; };
  window.__box = box;
  const dense = (P) => { const out = []; for (let i = 1; i < P.length; i++) { const [ax, ay] = P[i - 1], [bx, by] = P[i]; const n = Math.max(1, Math.round(Math.hypot(bx - ax, by - ay) / 4)); for (let k = 0; k < n; k++) out.push([ax + (bx - ax) * k / n, ay + (by - ay) * k / n]); } out.push(P[P.length - 1]); return out; };
  // a hand's copy: its own proportions, a little turned, a slow wander and a shake
  const hand = (lines, size) => {
    const sx = 0.85 + rnd() * 0.3, sy = 0.85 + rnd() * 0.3, a = (rnd() - 0.5) * 0.18;
    return lines.map((L) => { let wx = 0, wy = 0; return dense(L.map(([x, y]) => [(x - 12) * sx, (y - 12) * sy]).map(([x, y]) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a)]).map(([x, y]) => [x * size / 24, y * size / 24])).map(([x, y]) => { wx = wx * 0.9 + nrm() * 0.5; wy = wy * 0.9 + nrm() * 0.5; return [x + wx, y + wy]; }); });
  };
  const draw = (P, id) => {
    const touch = !!g.touch;
    const el = touch ? document.elementFromPoint(P[0][0], P[0][1]) : document.getElementById('fd-air');
    const ev = (type, [x, y]) => el.dispatchEvent(new PointerEvent(type, { clientX: x, clientY: y, pointerId: id, button: 0, buttons: type === 'pointerup' ? 0 : 1, pointerType: touch ? 'touch' : 'mouse', isPrimary: true, bubbles: true, cancelable: true }));
    ev('pointerdown', P[0]);
    for (const p of P.slice(1)) ev('pointermove', p);
    ev('pointerup', P[P.length - 1]);
  };
  window.__clear = () => { const v = g.player.inVehicle; if (v && v.fuse) { v.fuse.parts = []; v.fuse.decor = []; g.fuse.applyVeh(v); g.fuse.buildVeh(v); } g.fuse.pen.flights = []; return 1; };
  // the icon of a thing (or lines given), size px, at (screen), drawn wet in its category
  window.__wetIcon = (id, at, size, lines = null) => {
    const pen = g.fuse.pen;
    const it = pen.constructor && window.__ITEMS ? window.__ITEMS[id] : null;
    pen.pick(window.__CATOF[id]);
    const S = safe();
    const L = hand(lines || svgStrokes(window.__ITEMS[id].icon), size).map((P) => P.map(([x, y]) => [Math.min(S.x1, Math.max(S.x0, at[0] + x)), Math.min(S.y1, Math.max(S.y0, at[1] + y))]));
    L.forEach((P, k) => draw(P, 70 + k));
    return L.length;
  };
  return 1;
})();

(() => {
  // (ROADMAP 11.28) behaviour tests of the things of the pen: made on the car, then used
  const realNow = performance.now.bind(performance);
  window.__realNow = realNow;
  window.__frozen = null;
  performance.now = () => (window.__frozen !== null ? window.__frozen : realNow());
  window.__freeze = (t) => { window.__frozen = t; return 1; };
  window.__adv = (T) => { while (window.__tc + 1000 / 30 < T) { window.__tc += 1000 / 30; window.__frozen = window.__tc; g.update(1 / 30); } window.__tc = T; window.__frozen = T; return 1; };
  const V = () => g.player.inVehicle;
  window.__V = V;
  // the car on Collins Ave going north, the police gone
  window.__place = (x = -62.5, z = 120, yaw = Math.PI) => {
    const v = V();
    v.pos.set(x, 0, z); v.yaw = yaw; v.speed = 0; v.vy = 0; v.air = false;
    if (v.vx !== undefined) { v.vx = 0; v.vz = 0; }
    if (v.yawRate) v.yawRate = 0;
    g.camRig.yaw = yaw;
    g.police.clear();
    for (const c of [...g.traffic.list]) if (c.police || c.decoy) { g.traffic.removeCar(c); g.traffic.list.splice(g.traffic.list.indexOf(c), 1); }
    g.gear.live.length = 0;
    g.gear.rw = null; g.gear.freeze = 0; g.gear.slowUntil = 0; g.gear.slowReal = 0;
    document.querySelectorAll('.toast').forEach((e) => e.remove());
    // (the camera after it: two steps, standing)
    g.update(1 / 30); g.update(1 / 30);
    g.camera.updateMatrixWorld(true);
    return 1;
  };
  // a thing on the car: drawn (its icon), made as it, taken shape
  window.__mk = (id, lv, keep = false) => {
    if (!keep) __clear();
    g.gear.play.labLv = lv;
    const pen = g.fuse.pen;
    pen.made = null;
    if (!g.freedraw.isOpen) g.freedraw.show();
    g.freedraw.ink = 1;
    const b = __box(); const u = Math.max(b.w, b.h);
    __wetIcon(id, [b.x1 + u * 0.35, b.cy - u * 0.1], 150);
    pen.force = id;
    window.__t0 = realNow(); window.__tc = window.__t0; __freeze(window.__t0);
    g.freedraw.finishGroup();
    __adv(window.__t0 + 2400);
    __freeze(null);
    if (g.freedraw.isOpen) g.freedraw.close();
    const v = V();
    const p = v.fuse.parts.find((q) => q.item === id);
    window.__P = p;
    return p ? p.lv : 0;
  };
  // n frames, with these held: fire, guard (B), space, shift, w; pressed on the first: z, fireTap, guardTap
  window.__run = (n, o = {}) => {
    const inp = g.input;
    for (let i = 0; i < n; i++) {
      if (o.fire) { inp.fire = true; if (i === 0) inp.firePressed = true; }
      if (o.fireTap && i === 0) { inp.firePressed = true; }
      if (o.guard || (o.guardTap && i === 0)) inp.keys.add('KeyB'); else inp.keys.delete('KeyB');
      if (o.z && i === 0) inp.pressed.add('KeyZ');
      if (o.space) { inp.keys.add('Space'); if (i === 0) inp.pressed.add('Space'); }
      if (o.spaceTap && i === 0) inp.pressed.add('Space');
      if (o.shift) inp.keys.add('ShiftLeft');
      if (o.w) inp.keys.add('KeyW');
      if (o.each) o.each(i);
      g.update(1 / 30);
    }
    inp.fire = false; inp.firePressed = false;
    for (const k of ['KeyB', 'Space', 'ShiftLeft', 'KeyW']) inp.keys.delete(k);
    return 1;
  };
  // a police car at (lx, lz) in the car's frame (x to its left, z to its nose)
  window.__cop = (lx, lz, yawOff = 0, speed = 0) => {
    const v = V();
    const c = Math.cos(v.yaw), s = Math.sin(v.yaw);
    const car = g.traffic.policeCar(v.pos.x + lx * c + lz * s, v.pos.z - lx * s + lz * c, v.yaw + yawOff, [], 'pursuit');
    car.speed = speed;
    return car;
  };
  window.__r = (x) => Math.round(x * 100) / 100;
  return 1;
})();
